   214  static void
   215  test_parse_actions(const char *input)
   216  {
   217      struct shash symtab;
   218      struct hmap dhcp_opts;
   219      struct hmap dhcpv6_opts;
   220      struct hmap nd_ra_opts;
   221      struct simap ports;
   222
   223      create_symtab(&symtab);
   224      create_gen_opts(&dhcp_opts, &dhcpv6_opts, &nd_ra_opts);
   225
   226      /* Initialize group ids. */
   227      struct ovn_extend_table group_table;
   228      ovn_extend_table_init(&group_table);
   229
   230      /* Initialize meter ids for QoS. */
   231      struct ovn_extend_table meter_table;
   232      ovn_extend_table_init(&meter_table);
   233
   234      simap_init(&ports);
   235      simap_put(&ports, "eth0", 5);
   236      simap_put(&ports, "eth1", 6);
   237      simap_put(&ports, "LOCAL", ofp_to_u16(OFPP_LOCAL));
   238
   239      struct ofpbuf ovnacts;
   240      struct expr *prereqs;
   241      char *error;
   242
   243      puts(input);
   244
   245      ofpbuf_init(&ovnacts, 0);
   246
   247      const struct ovnact_parse_params pp = {
   248          .symtab = &symtab,
   249          .dhcp_opts = &dhcp_opts,
   250          .dhcpv6_opts = &dhcpv6_opts,
   251          .nd_ra_opts = &nd_ra_opts,
   252          .n_tables = 24,
   253          .cur_ltable = 10,
   254      };
   255      error = ovnacts_parse_string(input, &pp, &ovnacts, &prereqs);
   256      if (!error) {
   257          /* Convert the parsed representation back to a string and print it,
   258           * if it's different from the input. */
   259          struct ds ovnacts_s = DS_EMPTY_INITIALIZER;
   260          ovnacts_format(ovnacts.data, ovnacts.size, &ovnacts_s);
   261          if (strcmp(input, ds_cstr(&ovnacts_s))) {
   262              printf("    formats as %s\n", ds_cstr(&ovnacts_s));
   263          }
   264
   265          /* Encode the actions into OpenFlow and print. */
   266          const struct ovnact_encode_params ep = {
   267              .lookup_port = lookup_port_cb,
   268              .aux = &ports,
   269              .is_switch = true,
   270              .group_table = &group_table,
   271              .meter_table = &meter_table,
   272
   273              .pipeline = OVNACT_P_INGRESS,
   274              .ingress_ptable = 8,
   275              .egress_ptable = 40,
   276              .output_ptable = 64,
   277              .mac_bind_ptable = 65,
   278          };
   279          struct ofpbuf ofpacts;
   280          ofpbuf_init(&ofpacts, 0);
   281          ovnacts_encode(ovnacts.data, ovnacts.size, &ep, &ofpacts);
   282          struct ds ofpacts_s = DS_EMPTY_INITIALIZER;
   283          struct ofpact_format_params fp = { .s = &ofpacts_s };
   284          ofpacts_format(ofpacts.data, ofpacts.size, &fp);
   285          printf("    encodes as %s\n", ds_cstr(&ofpacts_s));
   286          ds_destroy(&ofpacts_s);
   287          ofpbuf_uninit(&ofpacts);
   288
   289          /* Print prerequisites if any. */
   290          if (prereqs) {
   291              struct ds prereqs_s = DS_EMPTY_INITIALIZER;
   292              expr_format(prereqs, &prereqs_s);
   293              printf("    has prereqs %s\n", ds_cstr(&prereqs_s));
   294              ds_destroy(&prereqs_s);
   295          }
   296
   297          /* Now re-parse and re-format the string to verify that it's
   298           * round-trippable. */
   299          struct ofpbuf ovnacts2;
   300          struct expr *prereqs2;
   301          ofpbuf_init(&ovnacts2, 0);
   302          error = ovnacts_parse_string(ds_cstr(&ovnacts_s), &pp, &ovnacts2,
   303                                       &prereqs2);
   304          if (!error) {
   305              struct ds ovnacts2_s = DS_EMPTY_INITIALIZER;
   306              ovnacts_format(ovnacts2.data, ovnacts2.size, &ovnacts2_s);
   307              if (strcmp(ds_cstr(&ovnacts_s), ds_cstr(&ovnacts2_s))) {
   308                  printf("    bad reformat: %s\n", ds_cstr(&ovnacts2_s));
   309              }
   310              ds_destroy(&ovnacts2_s);
   311          } else {
   312              printf("    reparse error: %s\n", error);
   313              free(error);
   314          }
   315          expr_destroy(prereqs2);
   316
   317          ovnacts_free(ovnacts2.data, ovnacts2.size);
   318          ofpbuf_uninit(&ovnacts2);
   319          ds_destroy(&ovnacts_s);
   320      } else {
   321          printf("    %s\n", error);
   322          free(error);
   323      }
   324
   325      expr_destroy(prereqs);
   326      ovnacts_free(ovnacts.data, ovnacts.size);
   327      ofpbuf_uninit(&ovnacts);
   328
   329      simap_destroy(&ports);
   330      expr_symtab_destroy(&symtab);
   331      shash_destroy(&symtab);
   332      dhcp_opts_destroy(&dhcp_opts);
   333      dhcp_opts_destroy(&dhcpv6_opts);
   334      nd_ra_opts_destroy(&nd_ra_opts);
   335      ovn_extend_table_destroy(&group_table);
   336      ovn_extend_table_destroy(&meter_table);
   337  }
