   357      simap_put(&ports, "lsp1", 0x11);
   358      simap_put(&ports, "lsp2", 0x12);
   359      simap_put(&ports, "lsp3", 0x13);
   360
   361      expr = expr_parse_string(input, &symtab, &addr_sets,
   362                               &port_groups, &error);
   363      if (!error) {
   364          expr = expr_annotate(expr, &symtab, &error);
   365      }
   366      if (!error) {
   367          expr = expr_simplify(expr, is_chassis_resident_cb, &ports);
   368          expr = expr_normalize(expr);
   369          ovs_assert(expr_is_normalized(expr));
   370      }
   371      if (!error) {
   372          struct hmap matches;
   373
   374          expr_to_matches(expr, lookup_port_cb, &ports, &matches);
   375          expr_matches_print(&matches, stdout);
   376          expr_matches_destroy(&matches);
   377      } else {
   378          puts(error);
   379          free(error);
   380      }
   381      expr_destroy(expr);
   382      simap_destroy(&ports);
   383      expr_symtab_destroy(&symtab);
   384      shash_destroy(&symtab);
   385      expr_const_sets_destroy(&addr_sets);
   386      shash_destroy(&addr_sets);
   387      expr_const_sets_destroy(&port_groups);
   388      shash_destroy(&port_groups);
